tool.command:
busco
--download_path '$out_file.extra_files_path'
#if $lineage == "virus"
    --download virus &&
#else
    --download all_'$lineage'$datasets_version &&
#end if
## unpack faa.gz files ready to use
## https://gitlab.com/ezlab/busco/-/issues/789
if [ -d '$out_file.extra_files_path'/lineages ]; then
    find '$out_file.extra_files_path'/lineages/ -name "*.faa.gz" -exec gunzip {} \;;
fi &&
## Galaxy joins command lines with spaces, so every statement below
## must carry its own terminating ";" where the shell needs one.
if [ -f '$out_file.extra_files_path/file_versions.tsv' ]; then
    while IFS="\$(printf '\t')" read -r dataset release_date upstream_hash domain file_type remainder; do
        if [ -n "\$file_type" ] && [ -d '$out_file.extra_files_path/lineages/'"\$dataset" ]; then
            printf '%s\t%s\t%s\t%s\t%s\n' "\$dataset" "\$release_date" "\$upstream_hash" "\$domain" "\$file_type";
        fi;
    done < '$out_file.extra_files_path/file_versions.tsv' | LC_ALL=C sort > '$out_file';
else
    : > '$out_file';
fi &&
if [ -s '$out_file' ]; then
    source_identity=\$(sha256sum '$out_file' | cut -d ' ' -f 1);
else
    (
        cd '$out_file.extra_files_path' &&
        find . -type f | LC_ALL=C sort |
        while IFS= read -r file; do
            relative_path=\${file#./};
            if [ "\$relative_path" != "file_versions.tsv" ]; then
                printf '%s\0' "\$relative_path";
                cat "\$file";
                printf '\0';
            fi;
        done
    ) > '$out_file' &&
    if [ ! -s '$out_file' ]; then
        echo "BUSCO did not download any data files" >&2;
        exit 1;
    fi &&
    source_identity=\$(sha256sum '$out_file' | cut -d ' ' -f 1);
fi &&
download_date=\$(date +%F) &&
sed -e "s/__SOURCE_DIGEST__/\$source_identity/g" -e "s/__DOWNLOAD_DATE__/\$download_date/g" '$dmjson' > '$out_file'.tmp &&
mv '$out_file'.tmp '$out_file'
